{"profile": {"name": "Sora", "age": 11, "communication_style": "single words or very short phrases"}, "activity": "Choose stretching, a slow walk, or watching from a chair in a gym.", "facts": ["Sora", "has", "said", "she", "enjoys", "stretching.", "She", "has", "not", "said", "whether", "her", "body", "hurts", "today.", "Stopping", "is", "always", "available."], "shared_context": "Held-out fictional case. Full communication access remains available. Cards are optional supplements, not claims about current intent.", "word_limit": 3}

